export const roomCode=value=>String(value||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8);
export function validPose(p){return p&&Array.isArray(p.p)&&p.p.length===3&&p.p.every(x=>Number.isFinite(x)&&Math.abs(x)<50000)&&Array.isArray(p.q)&&p.q.length===4&&p.q.every(x=>Number.isFinite(x)&&Math.abs(x)<=1.01)&&Math.hypot(...p.q)>.8&&Math.hypot(...p.q)<1.2&&Number.isFinite(p.s)&&p.s>=0&&p.s<=12000&&Number.isSafeInteger(p.seq)&&p.seq>=0;}
let peerLibrary;
function loadPeer(){if(globalThis.Peer)return Promise.resolve(globalThis.Peer);return peerLibrary??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/peerjs-1.5.5.min.js';s.onload=()=>resolve(globalThis.Peer);s.onerror=()=>{peerLibrary=null;reject(Error('Bağlantı kitaplığı yüklenemedi'));};document.head.append(s);});}
export class DriveRoom{
 constructor({status=()=>{},pose=()=>{},start=()=>{},connected=()=>{},left=()=>{},PeerClass=null}={}){this.callbacks={status,pose,start,connected,left};this.PeerClass=PeerClass;this.generation=0;this.offset=0;this.seq=-1;this.round='';}
 get ready(){return !!this.connection?.open;}
 async open(code,host){this.close();const generation=this.generation;this.host=host;this.code=roomCode(code);this.callbacks.status(host?'Oda oluşturuluyor…':'Odaya bağlanılıyor…');const Peer=this.PeerClass||await loadPeer();if(generation!==this.generation)return;this.peer=new Peer(host?'fatedreel-surus-1-'+this.code:undefined,{debug:0});this.callbacks.status(host?'Oda oluşturuluyor…':'Odaya bağlanılıyor…');this.timeout=setTimeout(()=>{if(!this.ready){this.callbacks.status('Bağlantı kurulamadı. Oda açık mı? Tekrar deneyebilir veya tek oynayabilirsin.');this.close(false);}},20000);
  this.peer.on('open',()=>{if(generation!==this.generation)return;if(host){clearTimeout(this.timeout);this.callbacks.status('Oda '+this.code+' · Arkadaşını bekliyor');}else this.attach(this.peer.connect('fatedreel-surus-1-'+this.code,{reliable:true,serialization:'json',metadata:{game:'surus-1'}}));});
  this.peer.on('connection',c=>{if(!host||this.connection||c.metadata?.game!=='surus-1'){c.on('open',()=>{c.send({type:'full'});setTimeout(()=>c.close(),100);});return;}this.attach(c);});
  this.peer.on('error',e=>{if(generation!==this.generation)return;this.callbacks.status(e.type==='unavailable-id'?'Bu oda kodu kullanımda. Yeni oda oluştur.':e.type==='peer-unavailable'?'Oda bulunamadı. Oda sahibinin sayfası açık olmalı.':'Bağlantı hatası. Yeniden deneyebilir veya tek oynayabilirsin.');this.close(false);});
 }
 attach(connection){this.connection=connection;const generation=this.generation;connection.on('open',()=>{if(generation!==this.generation)return;clearTimeout(this.timeout);this.callbacks.status('2/2 oyuncu · '+(this.host?'Başlatabilirsin':'Oda sahibinin başlatması bekleniyor'));this.callbacks.connected(this.host);if(!this.host){this.send({type:'ping',at:Date.now()});this.pingTimer=setInterval(()=>this.send({type:'ping',at:Date.now()}),4000);}});connection.on('data',m=>{if(generation===this.generation)this.receive(m);});connection.on('close',()=>{if(generation!==this.generation)return;this.connection=null;clearInterval(this.pingTimer);this.callbacks.left();this.callbacks.status(this.host?'Arkadaşın ayrıldı · Yeni bağlantı bekleniyor':'Oda bağlantısı kapandı · Tek oynayabilirsin');});connection.on('error',()=>this.callbacks.status('Oyuncu bağlantısında sorun oluştu.'));
 }
 send(message){if(this.ready)try{this.connection.send(message);}catch{this.callbacks.status('Bağlantı kesiliyor…');}}
 receive(m){if(!m||typeof m!=='object')return;if(m.type==='full'){this.callbacks.status('Oda dolu (2 kişi).');this.close(false);}else if(m.type==='ping'&&this.host&&Number.isFinite(m.at))this.send({type:'pong',at:m.at,server:Date.now()});else if(m.type==='pong'&&!this.host&&Number.isFinite(m.at)&&Number.isFinite(m.server))this.offset=m.server-(m.at+Date.now())/2;else if(m.type==='start'&&!this.host&&typeof m.round==='string'&&m.round.length<80&&Number.isFinite(m.at)){this.round=m.round;this.seq=-1;this.callbacks.start(m.at-this.offset,m.round);}else if(m.type==='pose'&&validPose(m)&&m.seq>this.seq){this.seq=m.seq;this.callbacks.pose(m);}}
 startRace(){if(!this.host||!this.ready)return false;const round=crypto.randomUUID(),at=Date.now()+3500;this.round=round;this.seq=-1;this.send({type:'start',at,round});this.callbacks.start(at,round);return true;}
 close(resetStatus=true){this.generation++;clearTimeout(this.timeout);clearInterval(this.pingTimer);this.connection?.close();this.peer?.destroy();this.connection=null;this.peer=null;this.seq=-1;this.callbacks.left();if(resetStatus)this.callbacks.status('Tek oyunculu sürüş');}
}
